#!/usr/bin/env python3
"""Selected identity HTTP transport and local adapter mutations in isolated copies, with raw evidence."""
import hashlib,json,os,pathlib,re,shutil,subprocess,tempfile
ROOT=pathlib.Path(__file__).resolve().parents[2]
LANG="go" if (ROOT/"go.mod").exists() else "rs" if (ROOT/"Cargo.toml").exists() else "nest"
EVIDENCE=pathlib.Path(tempfile.mkdtemp(prefix="n2f-auth-transport-mutations-"))
WORK=EVIDENCE/"work"
shutil.copytree(ROOT,WORK,ignore=shutil.ignore_patterns(".git","node_modules","target","dist","notes",".env","coverage"))
if LANG=="nest":(WORK/"node_modules").symlink_to(ROOT/"node_modules",target_is_directory=True)
NODE24=os.path.expanduser("~/.nvm/versions/node/v24.19.0/bin")
ENV={**os.environ,"PATH":NODE24+os.pathsep+os.environ.get("PATH",""),"GOCACHE":"/private/tmp/n2f-http-go-cache","CARGO_TARGET_DIR":"/private/tmp/n2f-identity-mutations-rs","CARGO_TERM_COLOR":"never","NO_COLOR":"1"}
DIRS={"go":".","rs":".","nest":"."}
COMMANDS={"go":["go","test","-count=1","./internal/identity/transport/...","./internal/identity/infra/local/..."],
"rs":["cargo","test","--offline","--locked","--test","identity_transport_spec","--test","identity_local_spec"],
"nest":["pnpm","exec","vitest","run","src/modules/identity/transport","src/modules/identity/infra/local"]}
# (name, file under the identity directory, old, new); old must occur exactly once.
MUTATIONS={
"go":[["origin_check_skipped", "internal/identity/transport/http/admission.go", "\tif len(values) != 1 || !t.origins[values[0]] {", "\tif len(values) < 0 {"], ["csrf_binding_ignored", "internal/identity/transport/http/admission.go", "if e := t.checkCSRF(req, session.binding); e != nil {", "if e := t.checkCSRF(req, anonymousBinding); e != nil {"], ["csrf_lifetime_unchecked", "internal/identity/transport/http/admission.go", "\tif issued > now || now-issued > t.cfg.CSRFTTL.Milliseconds() {", "\tif issued < 0 || now < 0 {"], ["duplicate_session_cookie_tolerated", "internal/identity/transport/http/admission.go", "\tif len(values) > 1 {\n\t\treturn admitted{}, t.rejectSession()\n\t}\n", ""], ["login_returns_token", "internal/identity/transport/http/handlers.go", "\"idle_expires_at_ms\": result.IdleExpiresAtMS, \"csrf_token\": token}", "\"idle_expires_at_ms\": result.IdleExpiresAtMS, \"csrf_token\": token, \"token\": result.Token.Reveal()}"], ["refusal_reveals_field", "internal/identity/transport/http/handlers.go", "\tresult, e := t.deps.Login.Login(ctx, w, command.LoginInput{Email: body.Email, Password: secret.New(body.Password), Source: req.Source()})\n\tif e != nil {\n\t\treturn refuse(e)\n\t}", "\tresult, e := t.deps.Login.Login(ctx, w, command.LoginInput{Email: body.Email, Password: secret.New(body.Password), Source: req.Source()})\n\tif e != nil {\n\t\treturn refuse(faults.New(faults.Unauthenticated, \"wrong password\").WithType(\"identity.credentials_rejected\").WithField(\"password\", \"mismatch\"))\n\t}"], ["source_bucket_ignored", "internal/identity/infra/local/limiter.go", "\tif srcb != nil {", "\tif false {"], ["fail_open_when_full", "internal/identity/infra/local/limiter.go", "\t\tif len(l.buckets) >= l.cfg.MaxKeys {\n\t\t\treturn nil, dependency()\n\t\t}", "\t\tif false {\n\t\t\treturn nil, dependency()\n\t\t}"], ["blocklist_substring_match", "internal/identity/infra/local/blocklist.go", "\t_, blocked := b.entries[fold(password.Secret().Reveal())]", "\tblocked := false\n\tfor entry := range b.entries {\n\t\tif strings.Contains(fold(password.Secret().Reveal()), entry) {\n\t\t\tblocked = true\n\t\t}\n\t}"]],
"rs":[["origin_check_skipped", "src/domains/identity/transport/http/mod.rs", "[one] if self.config.allowed_origins.iter().any(|o| o == one) => Ok(()),", "[one] if !one.is_empty() => Ok(()),"], ["csrf_binding_ignored", "src/domains/identity/transport/http/mod.rs", ".verify(\"csrf\", &Self::csrf_message(&nonce, issued, binding), &tag)?", ".verify(\"csrf\", &Self::csrf_message(&nonce, issued, ANONYMOUS), &tag)?"], ["csrf_lifetime_unchecked", "src/domains/identity/transport/http/mod.rs", "if nonce.len() != 16 || issued > now || now - issued > self.config.csrf_ttl_ms {", "if nonce.len() != 16 {"], ["duplicate_session_cookie_tolerated", "src/domains/identity/transport/http/mod.rs", "            [one] => {\n                let secret = SecretString::new(one.clone());", "            [one, ..] => {\n                let secret = SecretString::new(one.clone());"], ["login_returns_token", "src/domains/identity/transport/http/mod.rs", "        \"csrf_token\": token,\n    }))", "        \"csrf_token\": token,\n        \"session_token\": issued.secret.reveal(),\n    }))"], ["refusal_reveals_field", "src/domains/identity/transport/http/mod.rs", "                .with_type(\"identity.credentials_rejected\"),", "                .with_type(\"identity.credentials_rejected\")\n                .with_field(\"password\", \"mismatch\"),"], ["source_bucket_ignored", "src/domains/identity/infra/local/mod.rs", "for (key, bucket) in [subject_key, source_key].into_iter().flatten() {", "for (key, bucket) in [subject_key].into_iter().flatten() {"], ["fail_open_when_full", "src/domains/identity/infra/local/mod.rs", "return Err(dependency_failed(\"limiter store full\"));", "return Ok(None);"], ["blocklist_substring_match", "src/domains/identity/infra/local/mod.rs", "!self.entries.contains(&fold(password.secret().reveal()))", "!self.entries.iter().any(|e| fold(password.secret().reveal()).contains(e))"]],
"nest":[["origin_check_skipped", "src/modules/identity/transport/http/index.ts", "      if (post && !this.#origin(request)) return this.#refuse(originRejected());", "      if (false) return this.#refuse(originRejected());"], ["csrf_binding_ignored", "src/modules/identity/transport/http/index.ts", "      const binding = s.kind === 'admitted' ? s.binding : ANONYMOUS;", "      const binding = ANONYMOUS;"], ["csrf_lifetime_unchecked", "src/modules/identity/transport/http/csrf.ts", "  if (issuedAtMs > nowMs || nowMs - issuedAtMs > ttlMs) return false;", "  if (issuedAtMs > nowMs) return false;"], ["duplicate_session_cookie_tolerated", "src/modules/identity/transport/http/index.ts", "    if (values.length > 1)\n", "    if (false)\n"], ["login_returns_token", "src/modules/identity/transport/http/index.ts", "            absolute_expires_at_ms: r.value.absoluteExpiresAtMs,", "            absolute_expires_at_ms: r.value.absoluteExpiresAtMs,\n            token: r.value.token.reveal(),"], ["refusal_reveals_field", "src/modules/identity/transport/http/index.ts", "        if (!r.ok) return this.#failure(r.error, [this.#clearSession()]);", "        if (!r.ok)\n          return this.#failure(\n            failure('unauthenticated', 'password mismatch for ' + body.value.email, { type: 'identity.credentials_rejected' }),\n            [this.#clearSession()],\n          );"], ["source_bucket_ignored", "src/modules/identity/infra/local/limiter.ts", "    if (limits.source && source !== '') checks.push([limits.source, source]);\n", ""], ["fail_open_when_full", "src/modules/identity/infra/local/limiter.ts", "      if (this.#buckets.size >= this.#maxKeys) return err(dependencyFailed());\n", ""], ["blocklist_substring_match", "src/modules/identity/infra/local/blocklist.ts", "    return ok(!this.#entries.has(fold(password.secret().reveal())));", "    return ok(\n      ![...this.#entries].some((e) => fold(password.secret().reveal()).includes(e)),\n    );"]]}
originals={};hashes={}
for _,file,_,_ in MUTATIONS[LANG]:
 p=WORK/DIRS[LANG]/file
 if file not in originals:originals[file]=p.read_text();hashes[file]=hashlib.sha256(originals[file].encode()).hexdigest()
def run(name):
 p=subprocess.run(COMMANDS[LANG],cwd=WORK,env=ENV,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=600)
 (EVIDENCE/("transport_"+name+".log")).write_text(p.stdout);return p
assert MUTATIONS[LANG],"no mutation table for "+LANG
assert run("baseline").returncode==0,str(EVIDENCE)
results=[]
for name,file,old,new in MUTATIONS[LANG]:
 path=WORK/DIRS[LANG]/file;original=originals[file]
 assert original.count(old)==1,(name,file,old)
 path.write_text(original.replace(old,new,1))
 result=run(name)
 compiled=not re.search(r"error\[E\d+\]|error TS\d+|\[build failed\]|Transform failed|Failed to load|cannot use|undefined:",result.stdout)
 caught=result.returncode!=0 and compiled and ("FAIL" in result.stdout or "panicked at" in result.stdout)
 results.append({"name":name,"file":file,"caught":caught,"compiled":compiled,"source_sha256":hashes[file]})
 path.write_text(original)
assert run("restored").returncode==0
for file,digest in hashes.items():assert hashlib.sha256((ROOT/DIRS[LANG]/file).read_bytes()).hexdigest()==digest,"original source changed"
report={"language":LANG,"caught":sum(r["caught"] for r in results),"selected":len(results),"exhaustive":False,"evidence":str(EVIDENCE),"cases":results,"logs":sorted(p.name for p in EVIDENCE.glob("transport_*.log"))}
(EVIDENCE/"transport-mutation-evidence.json").write_text(json.dumps(report,indent=2))
print(json.dumps(report,indent=2));assert all(r["caught"] for r in results)
